var seed = 20240611;
function rnd() { seed = (seed + 0x6D2B79F5) | 0; var t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }
function gauss() { return Math.sqrt(-2 * Math.log(rnd() + 1e-9)) * Math.cos(6.2832 * rnd()); }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function ramp(t, a, b) { return clamp((t - a) / (b - a), 0, 1); }
function ease(x) { return x * x * (3 - 2 * x); }

var NB = 14;
var chain = [];
(function () {
  var x = 0, y = 0, a = 0, i, cx = 0, cy = 0, mr = 0;
  for (i = 0; i < NB; i++) { chain.push([x, y]); a += (rnd() - 0.5) * 1.5 + 0.3; x += Math.cos(a); y += Math.sin(a); }
  for (i = 0; i < NB; i++) { cx += chain[i][0] / NB; cy += chain[i][1] / NB; }
  for (i = 0; i < NB; i++) { chain[i][0] -= cx; chain[i][1] -= cy; mr = Math.max(mr, Math.hypot(chain[i][0], chain[i][1])); }
  for (i = 0; i < NB; i++) { chain[i][0] /= mr; chain[i][1] /= mr; }
})();

var NP = 12;
var panels = [];
(function () {
  for (var i = 0; i < NP; i++) {
    var z = -1.7 + 3.4 * i / (NP - 1);
    var sig = Math.exp(-1.1 + 0.8 * z);
    var p = { sig: sig, th: (rnd() * 2 - 1) * 3.0, n: [], e: [], loss: 0 };
    var s = 0.03 + 0.1 * sig, sum = 0;
    for (var j = 0; j < NB; j++) {
      var nx = gauss(), ny = gauss(), ex = gauss() * s, ey = gauss() * s;
      p.n.push([nx, ny]); p.e.push([ex, ey]); sum += ex * ex + ey * ey;
    }
    p.loss = sum / NB;
    panels.push(p);
  }
})();

var PERIOD = 14;
var phases = ['run the trunk once per example', 'reuse c for many noised copies (AF3: 48)', 'the denoiser gets 48 training signals for one trunk pass'];
var INK = '#04204B', SEC = '#3D5F91', GUIDE = '#8098BC', BLUE = '#0B4FC0', WARM = '#B4552F';

function arrow(ctx, x1, y1, x2, y2) {
  var a = Math.atan2(y2 - y1, x2 - x1);
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - 7 * Math.cos(a - 0.45), y2 - 7 * Math.sin(a - 0.45));
  ctx.lineTo(x2 - 7 * Math.cos(a + 0.45), y2 - 7 * Math.sin(a + 0.45));
  ctx.closePath(); ctx.fill();
}

function draw(ctx, width, height, time, dt) {
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, width, height);
  var t = time % PERIOD;
  var g = 1 - ease(ramp(t, 13, 14));
  var wide = width >= 560;
  var m = 12, gap = wide ? 6 : 5;
  var sBox, tBox, cPt, gx, gy, gw, gh, labelY;
  if (wide) {
    var Lw = Math.max(130, Math.min(190, width * 0.22));
    sBox = { x: m, y: 58, w: Lw, h: 110 };
    tBox = { x: m, y: 216, w: Lw, h: 86 };
    cPt = { x: m + Lw, y: 259 };
    gx = m + Lw + 34; gy = 58; labelY = 48;
  } else {
    sBox = { x: m, y: 32, w: 96, h: 78 };
    tBox = { x: m + 122, y: 36, w: width - 2 * m - 122, h: 70 };
    cPt = { x: m + 122 + (width - 2 * m - 122) / 2, y: 106 };
    gx = m; gy = 134; labelY = 124;
  }
  gw = width - m - gx; gh = height - (wide ? 10 : 8) - gy;
  var pw = (gw - 3 * gap) / 4, ph = (gh - 2 * gap) / 3;

  // caption
  var pi = t < 4.5 ? 0 : (t < 9.5 ? 1 : 2);
  var pst = pi === 0 ? 0 : (pi === 1 ? 4.5 : 9.5);
  var ca = ease(ramp(t - pst, 0, 0.5));
  if (pi === 2) ca *= 1 - ramp(t, 13.3, 13.9);
  var fs = 13;
  ctx.textAlign = 'center';
  ctx.font = fs + 'px sans-serif';
  while (fs > 11 && ctx.measureText(phases[pi]).width > width - 16) { fs--; ctx.font = fs + 'px sans-serif'; }
  ctx.globalAlpha = ca; ctx.fillStyle = INK;
  ctx.fillText(phases[pi], width / 2, 18);
  ctx.globalAlpha = 1;

  ctx.font = '12px sans-serif';
  ctx.textAlign = 'left';

  // ground truth box
  ctx.strokeStyle = GUIDE; ctx.lineWidth = 1;
  ctx.strokeRect(sBox.x, sBox.y, sBox.w, sBox.h);
  var sR = Math.min(sBox.w, sBox.h - 18) * 0.4;
  var scx = sBox.x + sBox.w / 2, scy = sBox.y + (sBox.h - 16) / 2;
  ctx.strokeStyle = INK; ctx.lineWidth = 2; ctx.beginPath();
  for (var j = 0; j < NB; j++) { var qx = scx + chain[j][0] * sR, qy = scy + chain[j][1] * sR; if (j === 0) ctx.moveTo(qx, qy); else ctx.lineTo(qx, qy); }
  ctx.stroke();
  ctx.fillStyle = INK;
  for (j = 0; j < NB; j++) { ctx.beginPath(); ctx.arc(scx + chain[j][0] * sR, scy + chain[j][1] * sR, 3, 0, 6.2832); ctx.fill(); }
  ctx.fillStyle = SEC; ctx.font = '11px sans-serif';
  ctx.fillText('ground truth x', sBox.x + 6, sBox.y + sBox.h - 4);

  // trunk
  var prog = ease(ramp(t, 0.3, 4.2));
  var running = t > 0.3 && t < 4.2;
  ctx.strokeStyle = GUIDE; ctx.fillStyle = GUIDE; ctx.lineWidth = 1.5;
  if (wide) arrow(ctx, sBox.x + sBox.w / 2, sBox.y + sBox.h + 2, sBox.x + sBox.w / 2, tBox.y - 3);
  else arrow(ctx, sBox.x + sBox.w + 2, sBox.y + 38, tBox.x - 3, sBox.y + 38);
  ctx.strokeStyle = running ? BLUE : INK; ctx.lineWidth = running ? 2 : 1.5;
  ctx.strokeRect(tBox.x, tBox.y, tBox.w, tBox.h);
  ctx.fillStyle = INK; ctx.font = '12px sans-serif';
  ctx.fillText('trunk (runs once)', tBox.x + 10, tBox.y + 19);
  var bx = tBox.x + 10, bw = tBox.w - 20, by = tBox.y + (wide ? 30 : 28);
  ctx.strokeStyle = GUIDE; ctx.lineWidth = 1; ctx.strokeRect(bx, by, bw, 10);
  ctx.fillStyle = BLUE; ctx.fillRect(bx, by, bw * prog * g, 10);
  ctx.fillStyle = WARM; ctx.font = '12px sans-serif';
  ctx.fillText('expensive: O(N³)', tBox.x + 10, tBox.y + tBox.h - 12);
  var cOn = prog > 0.98 ? g : 0;
  ctx.beginPath(); ctx.arc(cPt.x, cPt.y, 5, 0, 6.2832);
  ctx.fillStyle = '#ffffff'; ctx.fill();
  ctx.strokeStyle = BLUE; ctx.lineWidth = 1.5; ctx.stroke();
  ctx.globalAlpha = cOn; ctx.fillStyle = BLUE; ctx.fill(); ctx.globalAlpha = 1;
  ctx.fillStyle = BLUE; ctx.font = '12px sans-serif';
  if (wide) ctx.fillText('c', cPt.x + 9, cPt.y - 8); else ctx.fillText('c', cPt.x + 9, cPt.y + 4);
  if (wide) {
    ctx.fillStyle = SEC; ctx.font = '11px sans-serif';
    ctx.fillText('c conditions all copies', m, 334);
    ctx.fillText('trunk passes: ' + (prog > 0.98 ? 1 : 0) + ' / 1', m, 350);
  }

  // grid label and counter
  var sumK = 0, i;
  for (i = 0; i < NP; i++) sumK += ease(ramp(t, 9.6 + i * 0.12, 10.8 + i * 0.12)) / NP;
  var nSig = Math.round(sumK * 48);
  ctx.font = '11px sans-serif'; ctx.fillStyle = SEC;
  ctx.fillText('diffusion batch · 12 of 48 shown', gx, labelY);
  ctx.textAlign = 'right'; ctx.fillStyle = BLUE;
  ctx.fillText('signals ' + nSig + '/48', gx + gw, labelY);
  ctx.textAlign = 'left';

  // fan lines (below panels)
  for (i = 0; i < NP; i++) {
    var col = i % 4, row = Math.floor(i / 4);
    var px = gx + col * (pw + gap), py = gy + row * (ph + gap);
    var t0 = 4.7 + i * 0.27;
    var u = ease(ramp(t, t0 - 0.4, t0 + 0.4));
    if (u <= 0) continue;
    var ex = px + pw / 2, ey = py + ph / 2;
    var c1x, c1y, c2x, c2y;
    if (wide) { c1x = cPt.x + (ex - cPt.x) * 0.5; c1y = cPt.y; c2x = c1x; c2y = ey; }
    else { c1x = cPt.x; c1y = cPt.y + (ey - cPt.y) * 0.5; c2x = ex; c2y = c1y; }
    ctx.strokeStyle = BLUE; ctx.globalAlpha = 0.3 * g; ctx.lineWidth = 1; ctx.beginPath();
    for (var s = 0; s <= 14; s++) {
      var v = u * s / 14, w = 1 - v;
      var bxp = w * w * w * cPt.x + 3 * w * w * v * c1x + 3 * w * v * v * c2x + v * v * v * ex;
      var byp = w * w * w * cPt.y + 3 * w * w * v * c1y + 3 * w * v * v * c2y + v * v * v * ey;
      if (s === 0) ctx.moveTo(bxp, byp); else ctx.lineTo(bxp, byp);
    }
    ctx.stroke(); ctx.globalAlpha = 1;
  }

  // panels
  var ta = pw >= 120 ? 16 : 28;
  var R = 0.4 * Math.min(pw, ph - ta);
  var br = pw >= 120 ? 2.6 : 2;
  for (i = 0; i < NP; i++) {
    var P = panels[i];
    col = i % 4; row = Math.floor(i / 4);
    px = gx + col * (pw + gap); py = gy + row * (ph + gap);
    t0 = 4.7 + i * 0.27;
    var k2 = ease(ramp(t, t0, t0 + 1.3));
    var kp = ease(ramp(t, 9.6 + i * 0.12, 10.8 + i * 0.12));
    ctx.fillStyle = '#ffffff'; ctx.fillRect(px, py, pw, ph);
    var pulse = (t > t0 && t < t0 + 1.3) ? 1 : 0;
    ctx.lineWidth = pulse ? 2 : 1;
    ctx.strokeStyle = pulse ? BLUE : GUIDE;
    ctx.globalAlpha = 0.35 + 0.65 * k2 * g;
    ctx.strokeRect(px, py, pw, ph);
    ctx.globalAlpha = 1;
    if (k2 <= 0) continue;
    ctx.globalAlpha = g;
    var ccx = px + pw / 2, ccy = py + (ph - ta) / 2;
    var th = P.th * k2, cs = Math.cos(th), sn = Math.sin(th);
    var rx = [], ry = [], nx2 = [], ny2 = [], pxs = [], pys = [];
    var x0 = px + 3, x1 = px + pw - 3, y0 = py + 3, y1 = py + ph - ta - 3;
    for (j = 0; j < NB; j++) {
      var ux = chain[j][0] * cs - chain[j][1] * sn, uy = chain[j][0] * sn + chain[j][1] * cs;
      var yx = ux + P.sig * 0.4 * k2 * P.n[j][0], yy = uy + P.sig * 0.4 * k2 * P.n[j][1];
      var fx = ux + P.e[j][0], fy = uy + P.e[j][1];
      rx.push(clamp(ccx + ux * R, x0, x1)); ry.push(clamp(ccy + uy * R, y0, y1));
      nx2.push(clamp(ccx + yx * R, x0, x1)); ny2.push(clamp(ccy + yy * R, y0, y1));
      var mx = yx + (fx - yx) * kp, my = yy + (fy - yy) * kp;
      pxs.push(clamp(ccx + mx * R, x0, x1)); pys.push(clamp(ccy + my * R, y0, y1));
    }
    // rotated truth
    ctx.strokeStyle = INK; ctx.lineWidth = 1; ctx.globalAlpha = 0.45 * g; ctx.beginPath();
    for (j = 0; j < NB; j++) { if (j === 0) ctx.moveTo(rx[j], ry[j]); else ctx.lineTo(rx[j], ry[j]); }
    ctx.stroke();
    // noised copy
    ctx.globalAlpha = 0.85 * g * (1 - 0.5 * kp); ctx.strokeStyle = WARM; ctx.lineWidth = 1;
    for (j = 0; j < NB; j++) { ctx.beginPath(); ctx.arc(nx2[j], ny2[j], br, 0, 6.2832); ctx.stroke(); }
    // prediction
    if (kp > 0) {
      ctx.globalAlpha = Math.min(1, kp * 4) * g; ctx.strokeStyle = BLUE; ctx.fillStyle = BLUE; ctx.lineWidth = 1.6;
      ctx.beginPath();
      for (j = 0; j < NB; j++) { if (j === 0) ctx.moveTo(pxs[j], pys[j]); else ctx.lineTo(pxs[j], pys[j]); }
      ctx.stroke();
      for (j = 0; j < NB; j++) { ctx.beginPath(); ctx.arc(pxs[j], pys[j], br * 0.6, 0, 6.2832); ctx.fill(); }
    }
    // text
    ctx.globalAlpha = g; ctx.font = '11px sans-serif'; ctx.textAlign = 'left';
    var ty = py + ph - ta;
    var sTxt = 'σ=' + P.sig.toFixed(2);
    var lTxt = 'L=' + P.loss.toFixed(3);
    ctx.fillStyle = WARM;
    if (ta === 16) {
      ctx.fillText(sTxt, px + 5, ty + 11);
      ctx.globalAlpha = g * ease(ramp(kp, 0.7, 1));
      ctx.fillStyle = BLUE; ctx.textAlign = 'right';
      ctx.fillText(lTxt, px + pw - 5, ty + 11);
    } else {
      ctx.fillText(sTxt, px + 4, ty + 11);
      ctx.globalAlpha = g * ease(ramp(kp, 0.7, 1));
      ctx.fillStyle = BLUE;
      ctx.fillText(lTxt, px + 4, ty + 24);
    }
    ctx.textAlign = 'left'; ctx.globalAlpha = 1;
  }

  // legend (wide only, left column bottom)
  if (wide) {
    ctx.font = '11px sans-serif';
    ctx.fillStyle = INK; ctx.fillText('— rotated truth', m, 372);
    ctx.fillStyle = WARM; ctx.fillText('○ noised copy', m, 386);
    ctx.fillStyle = BLUE; ctx.fillText('● prediction', m + 88, 386);
  }
}

return { draw: draw };
